# AI-written: inverted dropout as a function, and the Keras equivalent
def dropout(x, rate, training):
    if not training:
        return x
    mask = np.random.rand(*x.shape) >= rate
    return x * mask / (1.0 - rate)

from keras import layers
layers.Dropout(0.5)   # same behaviour; identity at inference
